CREATE OR REPLACE FUNCTION public.rw_answer(p_id uuid, p_task uuid, p_index integer, p_answer text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare target text; ok boolean;begin
select t.words->p_index->>'en' into target from public.rw_tasks t join public.rw_members m on m.user_id=auth.uid() where t.id=p_task and m.role='student' and m.password_changed and (t.cohort is null or t.cohort=m.cohort) and p_index>=0;
if p_task is null and p_index>=0 and exists(select from public.rw_members where user_id=auth.uid() and role='student' and password_changed) then target=('["discover","balloon","wheel","central","although","attach","pull","international","path","technique","depend","describe","decide","develop","practice","improve","knowledge","journey","prepare","remember"]'::jsonb)->>p_index;end if;
if target is null then raise exception 'invalid task'; end if;
ok=lower(trim(target))=lower(trim(p_answer));insert into public.rw_answers values(p_id,auth.uid(),lower(trim(target)),ok,now()) on conflict do nothing;return ok;end$function$

CREATE OR REPLACE FUNCTION public.rw_reset_student_password(p_student uuid, p_password text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not exists(select 1 from public.rw_members where user_id=auth.uid() and role='teacher') then raise exception 'teacher required' using errcode='42501'; end if;
 if p_password is null or char_length(p_password)<8 or octet_length(p_password)>72 or trim(p_password)='' then raise exception 'invalid temporary password'; end if;
 perform 1 from public.rw_members where user_id=p_student and role='student' for update;
 if not found then raise exception 'student required'; end if;
 update auth.users set encrypted_password=extensions.crypt(p_password,extensions.gen_salt('bf',10)),updated_at=now() where id=p_student;
 update public.rw_members set password_changed=false where user_id=p_student;
 delete from auth.sessions where user_id=p_student;
end $function$

CREATE OR REPLACE FUNCTION public.rw_practice(p_id uuid, p_mode text, p_task uuid, p_index integer, p_word text, p_choice text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); grp text; w jsonb; k text; oldstage int; due timestamptz; st int; ok boolean; days int[]:=array[1,2,4,7,15,30]; prior boolean;
begin
select cohort into grp from public.rw_members where user_id=uid and role='student' and password_changed;
if not found or p_mode not in ('task','self','quiz','review') or p_mode is null then raise exception 'invalid access';end if;
perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
select correct into prior from public.rw_answers where id=p_id and student=uid;if found then return prior;end if;
if p_mode='review' then select jsonb_build_object('en',word,'zh',meaning) into w from public.rw_review_cards where student=uid and word=p_word;
elsif p_index>=0 and p_task is not null then select words->p_index into w from public.rw_tasks where id=p_task and (cohort is null or cohort=grp);
if w is null and p_mode in ('self','quiz') then select words->p_index into w from public.rw_libraries where id=p_task;end if;
elsif p_index>=0 and p_mode<>'task' then w='[{"en":"discover","zh":"发现；发觉"},{"en":"balloon","zh":"气球"},{"en":"wheel","zh":"轮子"},{"en":"central","zh":"中心的"},{"en":"although","zh":"虽然；尽管"},{"en":"attach","zh":"系上；连接"},{"en":"pull","zh":"拉；拖"},{"en":"international","zh":"国际的"},{"en":"path","zh":"小路；路径"},{"en":"technique","zh":"技术；技巧"},{"en":"depend","zh":"依靠；取决于"},{"en":"describe","zh":"描述"},{"en":"decide","zh":"决定"},{"en":"develop","zh":"发展；培养"},{"en":"practice","zh":"练习"},{"en":"improve","zh":"提高；改善"},{"en":"knowledge","zh":"知识"},{"en":"journey","zh":"旅程"},{"en":"prepare","zh":"准备"},{"en":"remember","zh":"记住"}]'::jsonb->p_index;end if;
k=lower(trim(w->>'en'));if k is null or p_choice is null then raise exception 'invalid word';end if;
ok=k=lower(trim(p_choice));
insert into public.rw_answers(id,student,word,correct) values(p_id,uid,k,ok);
select stage,due_at into oldstage,due from public.rw_review_cards where student=uid and word=k;
if not ok or due is null or due<=now() then
st=case when ok then least(6,coalesce(oldstage,0)+1) else 0 end;
insert into public.rw_review_cards values(uid,k,w->>'zh',st,case when ok then now()+make_interval(days=>days[st]) else now()+interval '10 minutes' end)
on conflict(student,word) do update set stage=excluded.stage,due_at=excluded.due_at,meaning=excluded.meaning;
end if;

return ok;end$function$

CREATE OR REPLACE FUNCTION public.rw_begin_mastery(p_kind text, p_source uuid, p_mode text DEFAULT NULL::text, p_restart boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); b jsonb; pool jsonb; mode_value text; version text; session public.rw_mastery_sessions;
 questions jsonb:='[]'; candidates jsonb; options jsonb; q jsonb; w jsonb; item record;
begin
 b:=rw_private.mastery_source(p_kind,p_source);
 mode_value:=coalesce(p_mode,b->>'category');
 if mode_value not in ('reading','writing') then raise exception 'invalid_mode';end if;
 pool:=b->'words';version:=md5(pool::text);
 if jsonb_array_length(pool)=0 then raise exception 'empty_book';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 select * into session from public.rw_mastery_sessions
 where student=uid and source_key=b->>'source_key' and mode=mode_value and status='active' for update;
 if found and not p_restart and session.source_version=version then return to_jsonb(session)-'student';end if;
 if session.id is not null then update public.rw_mastery_sessions set status='abandoned' where id=session.id;end if;
 -- Round-robin random sampling across teacher-labelled difficulty bands.
 for item in
  with ranked as (
   select value w,row_number() over(partition by value->>'difficulty' order by random()) band_rank,random() tie
   from jsonb_array_elements(pool)
  ), sample as (
   select * from ranked order by band_rank,tie limit least(20,jsonb_array_length(pool))
  )
  select sample.w from sample order by (sample.w->>'difficulty')::int,
    length(regexp_replace(sample.w->>'en','[^A-Za-z]','','g')),tie
 loop
  w:=item.w;options:='[]';
  if mode_value='reading' then
   candidates:=pool||'[{"en":"discover","zh":"发现；发觉","pos":"v.","example":"We hope to discover a new star.","translation":"我们希望发现一颗新星。"},{"en":"balloon","zh":"气球","pos":"n.","example":"The red balloon flew away.","translation":"那个红气球飞走了。"},{"en":"wheel","zh":"轮子","pos":"n.","example":"My bike has a broken wheel.","translation":"我的自行车有一个轮子坏了。"},{"en":"central","zh":"中心的","pos":"adj.","example":"Meet me at the central station.","translation":"在中心车站和我见面吧。"},{"en":"although","zh":"虽然；尽管","pos":"conj.","example":"Although it was cold, we went outside.","translation":"虽然天气很冷，我们还是出门了。"},{"en":"attach","zh":"系上；连接","pos":"v.","example":"Please attach a photo to your email.","translation":"请在邮件中附上一张照片。"},{"en":"pull","zh":"拉；拖","pos":"v.","example":"Please pull the door open.","translation":"请把门拉开。"},{"en":"international","zh":"国际的","pos":"adj.","example":"She studies at an international school.","translation":"她在一所国际学校学习。"},{"en":"path","zh":"小路；路径","pos":"n.","example":"Follow the path to the lake.","translation":"沿着小路走到湖边。"},{"en":"technique","zh":"技术；技巧","pos":"n.","example":"Our coach taught us a new swimming technique.","translation":"教练教了我们一种新的游泳技巧。"},{"en":"depend","zh":"依靠；取决于","pos":"v.","example":"Young birds depend on their parents.","translation":"幼鸟依靠父母生活。"},{"en":"describe","zh":"描述","pos":"v.","example":"Can you describe your room?","translation":"你能描述一下你的房间吗？"},{"en":"decide","zh":"决定","pos":"v.","example":"We must decide where to go.","translation":"我们必须决定去哪里。"},{"en":"develop","zh":"发展；培养","pos":"v.","example":"We can develop good habits at school.","translation":"我们可以在学校培养好习惯。"},{"en":"practice","zh":"练习","pos":"v.","example":"We practice English after school.","translation":"我们放学后练习英语。"},{"en":"improve","zh":"提高；改善","pos":"v.","example":"Reading helps me improve my English.","translation":"阅读帮助我提高英语水平。"},{"en":"knowledge","zh":"知识","pos":"n.","example":"Books give us knowledge.","translation":"书籍给我们知识。"},{"en":"journey","zh":"旅程","pos":"n.","example":"Our journey began on Monday.","translation":"我们的旅程从星期一开始。"},{"en":"prepare","zh":"准备","pos":"v.","example":"Let''s prepare lunch together.","translation":"我们一起准备午餐吧。"},{"en":"remember","zh":"记住","pos":"v.","example":"I remember your name.","translation":"我记得你的名字。"}]'::jsonb;
   with distinct_choices as (
    select distinct on(rw_private.mastery_norm(v->>'zh')) v,random() shuffle
    from jsonb_array_elements(candidates) v
    where rw_private.mastery_norm(v->>'en')<>rw_private.mastery_norm(w->>'en')
      and nullif(btrim(v->>'zh'),'') is not null
      and not(regexp_split_to_array(rw_private.mastery_norm(v->>'zh'),'[;；、]') &&
              regexp_split_to_array(rw_private.mastery_norm(w->>'zh'),'[;；、]'))
    order by rw_private.mastery_norm(v->>'zh'),random()
   ), distractors as (
    select jsonb_build_object('en',v->>'en','zh',v->>'zh') v from distinct_choices
    order by case when v->>'pos'=w->>'pos' then 0 else 1 end,shuffle limit 3
   ), all_options as (
    select v from distractors union all select jsonb_build_object('en',w->>'en','zh',w->>'zh')
   )
   select jsonb_agg(v order by random()) into options from all_options;
   if jsonb_array_length(options)<>4 then raise exception 'not_enough_distinct_options';end if;
  end if;
  q:=w||jsonb_build_object('options',options);
  questions:=questions||jsonb_build_array(q);
 end loop;
 insert into public.rw_mastery_sessions(student,source_kind,source_id,source_key,mode,title,source_version,questions)
 values(uid,p_kind,p_source,b->>'source_key',mode_value,b->>'title',version,questions) returning * into session;
 return to_jsonb(session)-'student';
end $function$

CREATE OR REPLACE FUNCTION public.rw_check_familiar(p_id uuid, p_word text, p_choice text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); c public.rw_known_checks;ok boolean;
begin
 if not exists(select 1 from public.rw_members where user_id=uid and role='student' and password_changed) then raise exception 'student required';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 select correct into ok from public.rw_answers where student=uid and id=p_id;if found then return ok;end if;
 select * into c from public.rw_known_checks where student=uid and word=p_word and due_at<=now() and state<>'relearn';
 if not found then raise exception 'check no longer due';end if;
 ok:=coalesce(c.word=lower(trim(p_choice)),false);
 insert into public.rw_answers(id,student,word,correct) values(p_id,uid,c.word,ok);
 update public.rw_known_checks set state=case when ok then 'verified' else 'relearn' end,
 due_at=case when ok then now()+ interval '7 days'+ random()*interval '7 days' else now() end where student=uid and word=c.word;
 insert into public.rw_review_cards(student,word,meaning,stage,due_at) values(uid,c.word,c.meaning,case when ok then 1 else 0 end,case when ok then now()+interval '14 days' else now() end)
 on conflict(student,word) do update set meaning=excluded.meaning,stage=excluded.stage,due_at=excluded.due_at;
 return ok;
end $function$

CREATE OR REPLACE FUNCTION public.rw_skip_familiar(p_task uuid, p_index integer, p_word text, p_meaning text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); grp text; w jsonb; k text; m text;
begin
 select cohort into grp from public.rw_members where user_id=uid and role='student' and password_changed;
 if not found then raise exception 'student required'; end if;
 if p_task is not null then
 select words->p_index into w from public.rw_tasks where id=p_task and (cohort is null or cohort=grp) and p_index>=0;
 if w is null and p_index>=0 then select words->p_index into w from public.rw_libraries where id=p_task;end if;
k:=lower(trim(w->>'en'));m:=w->>'zh';
 else
 k:=lower(trim(p_word));m:=p_meaning;
 if not(k=any(array['discover','balloon','wheel','central','although','attach','pull','international','path','technique','depend','describe','decide','develop','practice','improve','knowledge','journey','prepare','remember'])) then raise exception 'unknown word'; end if;
 end if;
 if k is null or m is null or length(m)>500 then raise exception 'invalid word';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 insert into public.rw_known_checks values(uid,k,m,now()+interval '1 day' +random()*interval '2 days','pending') on conflict do nothing;
 if exists(select 1 from public.rw_known_checks where student=uid and word=k and (state='relearn' or due_at<=now())) then raise exception '请先完成这个词的抽查或重学';end if;
end $function$

CREATE OR REPLACE FUNCTION public.rw_submit_group(p_id uuid, p_title text, p_answers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); grp text; prior public.rw_group_tests; a jsonb; w jsonb; k text;
 refs jsonb:='[]'; seen text[]:='{}'; n int:=0; ok boolean; t uuid; idx int;
begin
 select cohort into grp from public.rw_members where user_id=uid and role='student' and password_changed;
 if not found then raise exception 'student required';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 select * into prior from public.rw_group_tests where id=p_id and student=uid;
 if found then return jsonb_build_object('correct',prior.correct,'passed',prior.correct>=9,'answers',prior.answers);end if;
 if p_answers is null or jsonb_typeof(p_answers)<>'array' or jsonb_array_length(p_answers)<>10 then raise exception 'exactly ten questions required';end if;
 if p_title is null or length(p_title)>200 then raise exception 'invalid title';end if;
 for a in select value from jsonb_array_elements(p_answers) loop
 t:=(a->>'task')::uuid;idx:=(a->>'index')::integer;
 if idx is null or idx<0 then raise exception 'invalid index';end if;
 if t is not null then select words->idx into w from public.rw_tasks where id=t and (cohort is null or cohort=grp);
 if w is null then select words->idx into w from public.rw_libraries where id=t;end if;
 else w:='[{"en":"discover","zh":"发现；发觉"},{"en":"balloon","zh":"气球"},{"en":"wheel","zh":"轮子"},{"en":"central","zh":"中心的"},{"en":"although","zh":"虽然；尽管"},{"en":"attach","zh":"系上；连接"},{"en":"pull","zh":"拉；拖"},{"en":"international","zh":"国际的"},{"en":"path","zh":"小路；路径"},{"en":"technique","zh":"技术；技巧"},{"en":"depend","zh":"依靠；取决于"},{"en":"describe","zh":"描述"},{"en":"decide","zh":"决定"},{"en":"develop","zh":"发展；培养"},{"en":"practice","zh":"练习"},{"en":"improve","zh":"提高；改善"},{"en":"knowledge","zh":"知识"},{"en":"journey","zh":"旅程"},{"en":"prepare","zh":"准备"},{"en":"remember","zh":"记住"}]'::jsonb->idx;end if;
 k:=lower(trim(w->>'en'));
 if k is null or k=any(seen) or a->>'choice' is null or length(a->>'choice')>300 then raise exception 'invalid or duplicate word';end if;
 seen:=array_append(seen,k);
 ok:=public.rw_practice(gen_random_uuid(),'quiz',t,idx,k,a->>'choice');
 if ok then n:=n+1;end if;
 refs:=refs||jsonb_build_array(jsonb_build_object('task',t,'index',idx,'word',k,'correct',ok));
 end loop;
 insert into public.rw_group_tests values(p_id,uid,p_title,now(),refs,n);
 if n>=9 then
 for a in select value from jsonb_array_elements(refs) loop
 if a->>'task' is not null and exists(select 1 from public.rw_tasks where id=(a->>'task')::uuid and (cohort is null or cohort=grp)) then insert into public.rw_progress(user_id,task_id,word_index) values(uid,(a->>'task')::uuid,(a->>'index')::integer) on conflict do nothing;end if;
 end loop;
 end if;
 return jsonb_build_object('correct',n,'passed',n>=9,'answers',refs);
end $function$

